// Общие шаги для тестов TAQO (прежнее имя — Tenderflow IL): сессии ролей, мастер /onboarding, тестовые файлы QA-AUTO-, drag&drop.
import { Page, Locator, expect } from '@playwright/test';
import * as path from 'path';

/** Путь к сохранённой сессии роли (.qa/auth/<role>.json). Пароли в тестах не используются. */
export const authState = (role: 'admin' | 'user' | 'admin2' | 'newadmin' | 'signup14') => path.resolve(__dirname, '../../../auth', `${role}.json`);

/** Уникальное имя тестовых данных: QA-AUTO-<feature>-<время>. */
export const qaName = (feature: string) => `QA-AUTO-${feature}-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

type QaFile = { name: string; mimeType: string; buffer: Buffer };

const MIME: Record<string, string> = {
  pdf: 'application/pdf',
  docx: 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  png: 'image/png',
  exe: 'application/x-msdownload',
};

/** Тестовый файл в памяти (подставляется через setInputFiles, без системного диалога). empty — 0 байт. */
export function qaFile(baseName: string, ext: 'pdf' | 'docx' | 'png' | 'exe', opts: { empty?: boolean } = {}): QaFile {
  const body =
    ext === 'pdf' ? '%PDF-1.4\n%QA-AUTO test file\n1 0 obj<<>>endobj\ntrailer<<>>\n%%EOF\n' :
    ext === 'exe' ? 'MZ QA-AUTO test executable' :
    'QA-AUTO test file';
  return { name: `${baseName}.${ext}`, mimeType: MIME[ext], buffer: opts.empty ? Buffer.alloc(0) : Buffer.from(body) };
}

/** Строка файла в списке «קבצים מצורפים». */
export const uploadItem = (page: Page, fileName: string): Locator =>
  page.getByRole('list', { name: 'קבצים מצורפים' }).getByRole('listitem').filter({ hasText: fileName });

/**
 * Перетаскивание файлов в зону загрузки (родитель поля input[type=file]) — синтетические dragover/drop
 * с DataTransfer, как при настоящем перетаскивании. Системный drag&drop проверяется вручную.
 */
export async function dropFiles(page: Page, fileInput: Locator, files: { name: string; mimeType: string; content: string }[]) {
  const zone = fileInput.locator('xpath=..');
  const dataTransfer = await page.evaluateHandle((fs) => {
    const dt = new DataTransfer();
    for (const f of fs) dt.items.add(new File([f.content], f.name, { type: f.mimeType }));
    return dt;
  }, files);
  await zone.dispatchEvent('dragover', { dataTransfer });
  await zone.dispatchEvent('drop', { dataTransfer });
}

// ---------- Мастер «הקמת פרופיל החברה» (/onboarding, 4 шага) ----------

export const WIZARD_STEPS = ['פרטי חברה', 'מידע להתאמת מכרזים', 'גורמים מקצועיים קבועים', 'מסמכים קבועים'] as const;

export const stepTitle = (page: Page) => page.getByRole('heading', { name: /^שלב \d מתוך 4:/ });

async function currentStep(page: Page): Promise<number> {
  await expect(stepTitle(page)).toBeVisible();
  const text = (await stepTitle(page).textContent()) ?? '';
  const n = Number(text.match(/שלב\s*(\d)/)?.[1]);
  if (!n) throw new Error(`Не удалось прочитать номер шага мастера из «${text}»`);
  return n;
}

/**
 * Открыть шаг N мастера. Мастер открывается на сохранённом шаге; переходим кнопками «הקודם» / «הבא»
 * (обе сохраняют текущий шаг на сервере). Галочки ✓ здесь не проверяем — они проверяются
 * в tests/onboarding-wizard/ (#bb57bd, исправлено и принято 10.11.2026).
 */
export async function openWizardStep(page: Page, n: 1 | 2 | 3 | 4) {
  await page.goto('/onboarding');
  for (let guard = 0; guard < 6; guard++) {
    const cur = await currentStep(page);
    if (cur === n) {
      await expect(stepTitle(page)).toHaveText(`שלב ${n} מתוך 4: ${WIZARD_STEPS[n - 1]}`);
      return;
    }
    const next = cur > n ? cur - 1 : cur + 1;
    await page.getByRole('button', { name: cur > n ? 'הקודם' : 'הבא', exact: true }).click();
    await expect(stepTitle(page)).toContainText(`שלב ${next} מתוך 4`);
  }
  throw new Error(`Не удалось перейти на шаг ${n} мастера`);
}

/** Вернуть мастер на шаг 4 — в состояние общего аккаунта до теста (онбординг компании пройден). */
export async function restoreWizard(page: Page) {
  await openWizardStep(page, 4);
}

/** Сегодняшняя дата в формате списка документов: «25.10.2026». */
export const todayHe = () =>
  new Intl.DateTimeFormat('he-IL', { timeZone: 'Asia/Jerusalem', day: '2-digit', month: '2-digit', year: 'numeric' }).format(new Date());
